/** 配置报告 fixture 深拷贝（防用例间引用残留），context 承载归属 root。 */
function configReportFor(root: string): WorkspaceConfigReport {
  const report = JSON.parse(JSON.stringify(WORKSPACE_CONFIG)) as WorkspaceConfigReport;
  report.config.context = root;
  return report;
}

// ---------------------------------------------------------------------------
// 进程边界 Mock：IPC 按命令名分发；文件夹对话框按用例 resolve / reject / cancel；
// 版本号固定 resolve。sonner <Toaster /> 不 mock：App 根真实挂载，toast 断言走
// DOM 文案 + waitFor。sonner toast 状态为模块级单例、跨用例存活，beforeEach
// 统一 dismiss 防残留。
// ---------------------------------------------------------------------------

let remaining: WorkspaceRecord[];
let addBehavior: 'ok' | 'reject' = 'ok';
let addRecord: WorkspaceRecord | null = null;
let listReject: string | null = null;
let configReject: string | null = null;
let configPending = false;
/// 架构页取数失败注入位（`archi_graph` reject 形态）
let archiReject: string | null = null;

/** 架构图 fixture（两元素零关系零诊断；`archi_graph` / `archi_module` 共用）。 */
const ARCHI_ELEMENTS = [
  {
    fqn: 'App',
    kind: 'package' as const,
    gate: 'off' as const,
    path: [],
    summary: null,
    metadata: {},
    modelFile: '.dev-team/architecture/models/01-core.toml',
    modelLine: 2,
    mark: 'none' as const,
  },
  {
    fqn: 'App.Auth',
    kind: 'domain' as const,
    gate: 'strict' as const,
    path: ['./src/auth/'],
    summary: '认证域',
    metadata: {},
    modelFile: '.dev-team/architecture/models/01-core.toml',
    modelLine: 6,
    mark: 'none' as const,
  },
];

// 构建模式单源（IPC `app_environment`）：默认 dev fixture（徽标在场、更新检查
// 不发起）；需检查路径的用例切 'prod'；另备 reject / pending / null / 非法载荷
// 四档表达「未就绪 / 取数失败 / 载荷不合法」。
const DEV_DATA_ROOT = 'C:\\u\\.dev-team\\dev';
const PROD_DATA_ROOT = 'C:\\u\\.dev-team';
const DEV_ENVIRONMENT = { mode: 'dev', dataRoot: DEV_DATA_ROOT, source: 'dev-default' };
const PROD_ENVIRONMENT = { mode: 'prod', dataRoot: PROD_DATA_ROOT, source: 'prod' };
let environmentMode: 'dev' | 'prod' | 'reject' | 'pending' | 'null' | 'invalid' = 'dev';

function mockIpc() {
  remaining = [FIRST, SECOND];
  addBehavior = 'ok';
  addRecord = null;
  listReject = null;
  configReject = null;
  configPending = false;
  archiReject = null;
  environmentMode = 'dev';
  invokeMock.mockImplementation(
    (command: string, params?: { root?: string; id?: string; offset?: number; limit?: number }) => {
      // 构建模式单源（壳层挂载一次）：dev / prod fixture 与 reject / pending /
      // null / 非法载荷四档（后四档落入「mode 未知」路径）
      if (command === 'app_environment') {
        if (environmentMode === 'reject') return Promise.reject(new Error('IPC 不可用'));
        if (environmentMode === 'pending') return new Promise<unknown>(() => {});
        if (environmentMode === 'null') return Promise.resolve(null);
        if (environmentMode === 'invalid') {
          return Promise.resolve({ mode: 'other', dataRoot: 5 });
        }
        return Promise.resolve(
          environmentMode === 'prod' ? { ...PROD_ENVIRONMENT } : { ...DEV_ENVIRONMENT },
        );
      }
      if (command === 'list_workspaces') {
        if (listReject !== null) return Promise.reject(new Error(listReject));
        return Promise.resolve([...remaining]);
      }
      // 移除面（选择器 UI 已不含移除入口——保留命令桩：导航 / 欢迎态用例的
      // 「零 remove 命令」负断言仍在场）
      if (command === 'remove_workspace') {
        remaining = remaining.filter((r) => r.root !== params?.root);
        return Promise.resolve(true);
      }
      if (command === 'add_workspace') {
        if (addBehavior === 'reject') {
          return Promise.reject(new Error('canonicalize: 入库失败'));
        }
        const rec: WorkspaceRecord = addRecord ?? {
          root: params?.root ?? '',
          name: 'picked',
          addedAt: 1,
        };
        // 对齐后端：库存按默认序（canonical root 升序）返回，新记录未必居首
        remaining = [...remaining.filter((r) => r.root !== rec.root), rec].sort((a, b) =>
          a.root < b.root ? -1 : a.root > b.root ? 1 : 0,
        );
        return Promise.resolve(rec);
      }
      if (command === 'list_changes') {
        return Promise.resolve(fakeList);
      }
      if (command === 'get_change_detail') {
        // 统一视图信封（detail ∪ activeRun——unify-run-state-persistence 线面）
        return Promise.resolve({ detail: fakeDetail, activeRun: null });
      }
      if (command === 'db_models') {
        return Promise.resolve(DB_MODELS.map((model) => ({ ...model })));
      }
      if (command === 'db_records') {
        const offset = params?.offset ?? 0;
        const limit = params?.limit ?? 50;
        const records = DB_RECORDS.slice(offset, offset + limit).map((e) => ({ ...e }));
        return Promise.resolve({ records, total: DB_RECORDS.length });
      }
      if (command === 'agent_sessions') {
        return Promise.resolve({ sessions: [], total: 0 });
      }
      if (command === 'agent_session_transcript') {
        return Promise.resolve([]);
      }
      // agent 选择器挂载取数（useAgentOptions 发起 list_agent_instances）：同回
      // 数组形态（null 会使实例清单置 null 而崩），页面切页断言不涉及其内容
      if (command === 'list_agent_instances') {
        return Promise.resolve([]);
      }
      // 基础信息页挂载取数（useCodeStats 挂载发起 code_stats）：回三面 DTO，
      // fixture 深拷贝防用例间引用残留
      if (command === 'code_stats') {
        return Promise.resolve(JSON.parse(JSON.stringify(CODE_STATS)) as CodeStatsReport);
      }
      // 配置页挂载取数（useWorkspaceConfig 挂载发起 workspace_config）：
      // resolve（context 归属 root）/ reject / 手动 pending 三态控制
      if (command === 'workspace_config') {
        if (configReject !== null) return Promise.reject(new Error(configReject));
        if (configPending) return new Promise<WorkspaceConfigReport>(() => {});
        return Promise.resolve(configReportFor(params?.root ?? ''));
      }
      // 架构页挂载取数（useArchiGraph 挂载发起 archi_graph）：正确形态回健康图；
      // reject 形态由 archiReject 控制（错误态用例）
      if (command === 'archi_graph') {
        if (archiReject !== null) return Promise.reject(new Error(archiReject));
        return Promise.resolve({ elements: [...ARCHI_ELEMENTS], relations: [], diagnostics: [] });
      }
      if (command === 'archi_module') {
        return Promise.resolve({
          element: ARCHI_ELEMENTS[0],
          dependsOn: [],
          dependedBy: [],
          children: [],
          docs: [],
          warnings: [],
        });
      }
      return Promise.resolve(null);
    },
  );
}

// ---------------------------------------------------------------------------
// 装置
// ---------------------------------------------------------------------------

/** mock.calls 中某命令的调用次数。 */
function countOf(command: string): number {
  return invokeMock.mock.calls.filter(([name]) => name === command).length;
}

/** 除壳层固有 `app_environment` 外的命令序列（环境取数次数单列断言）。 */
function commandsExceptEnvironment(): string[] {
  return invokeMock.mock.calls
    .map(([name]) => name as string)
    .filter((name) => name !== 'app_environment');
}

/** mock.calls 中某命令最近一次的入参对象（无调用即报错）。 */
function lastParamsOf(command: string): Record<string, unknown> {
  const calls = invokeMock.mock.calls.filter(([name]) => name === command);
  if (calls.length === 0) throw new Error(`命令 ${command} 无调用记录`);
  return calls.at(-1)?.[1] as Record<string, unknown>;
}

/** workspace 选择器 trigger（DropdownMenuTrigger 收敛到 data-slot）。 */
function workspaceTrigger(): HTMLElement {
  const trigger = document.querySelector<HTMLElement>('[data-slot="dropdown-menu-trigger"]');
  if (!trigger) throw new Error('workspace 选择器 trigger 不存在');
  return trigger;
}

/** 打开 workspace 选择器：base-ui Menu 以 mousedown 打开、开启动作为 frame
 * 异步执行，以菜单组标签「工作区」出现收敛最终态。 */
async function openWorkspaceMenu(): Promise<void> {
  fireEvent.mouseDown(workspaceTrigger());
  await screen.findByText('工作区');
}

/** 有记录启动：等待自动恢复第一名进入列表视图（列表已渲染）。 */
async function restored() {
  render(<App />);
  await waitFor(() =>
    expect(invokeMock).toHaveBeenCalledWith('list_changes', { root: FIRST.root }),
  );
  await waitFor(() => expect(screen.getByText('add-feature') !== null).toBe(true));
}

function fakeUpdate(version = '0.2.0') {
  return {
    version,
    body: '修复若干问题',
    close: vi.fn().mockResolvedValue(undefined),
    downloadAndInstall: vi.fn().mockResolvedValue(undefined),
  };
}

// 流程图区（建档详情，status 在场）挂载 ReactFlow：jsdom 缺口垫片（环境 stub
// 而非业务 mock）——进入详情视图的用例全局兜底（xyflow 边标签度量另需
// SVGGraphicsElement.getBBox 零包围盒垫片）
class ResizeObserverStub {
  observe = vi.fn();
  unobserve = vi.fn();
  disconnect = vi.fn();
}

beforeEach(() => {
  vi.stubGlobal('ResizeObserver', ResizeObserverStub);
  const svgPrototype = globalThis.SVGElement?.prototype as unknown as
    | Record<string, unknown>
    | undefined;
  if (svgPrototype !== undefined && typeof svgPrototype.getBBox !== 'function') {
    svgPrototype.getBBox = () => ({ x: 0, y: 0, width: 0, height: 0 });
  }
});

describe('App：启动恢复、欢迎屏清单与视图状态（AC-9）', () => {
  beforeEach(() => {
    // 路由化后 App 自含 HashRouter（design D6）：jsdom location 跨用例存活，
    // 上一用例残留的 hash 会改变下一用例启动路由初态，先重置
    window.location.hash = '';
    getVersionMock.mockReset();
    invokeMock.mockReset();
    openMock.mockReset();
    checkMock.mockReset();
    checkMock.mockResolvedValue(null);
    // useUpdater 挂载拉取版本号：走独立 mock，不混入 invoke 调用序列断言
    getVersionMock.mockResolvedValue('0.1.0');
    toast.dismiss(); // sonner 模块级 toast 状态跨用例存活：清残留
    mockIpc();
  });

  it('list_workspaces 返回空清单启动：呈现欢迎屏空态与「添加新文件夹」入口，不进入列表视图', async () => {
    remaining = [];
    render(<App />);

    await waitFor(() => expect(screen.getByText('添加新文件夹') !== null).toBe(true));

    expect(screen.getByText(/还没有记录/) !== null).toBe(true);
    expect(screen.getByText(/添加一个项目根目录开始浏览/) !== null).toBe(true);
    expect(screen.queryByRole('button', { name: '刷新' })).toBeNull();
    // 除挂载自动 load 与壳层环境取数外无任何取数
    expect(commandsExceptEnvironment().every((name) => name === 'list_workspaces')).toBe(true);
    expect(countOf('app_environment')).toBe(1);
  });

  it('HashRouter 显式关闭 transition：流式 sync 更新不再饿死导航', async () => {
    await restored();
    expect(vi.mocked(HashRouter).mock.calls.some(([props]) => props.useTransitions === false)).toBe(
      true,
    );
  });

  it('欢迎屏加载中：挂载取数未返回时呈现「加载中…」，清单返回后消失', async () => {
    let resolveLoad: (records: WorkspaceRecord[]) => void = () => {};
    invokeMock.mockImplementation((command: string) => {
      if (command === 'list_workspaces') {
        return new Promise<WorkspaceRecord[]>((resolve) => {
          resolveLoad = resolve;
        });
      }
      return Promise.resolve(null);
    });
    render(<App />);

    await waitFor(() => expect(screen.getByText('加载中…') !== null).toBe(true));
    await act(async () => {
      resolveLoad([]);
    });
    await waitFor(() => expect(screen.queryByText('加载中…')).toBeNull());
    // 加载结束仍未有根：停留欢迎屏空态
    expect(screen.getByText('添加新文件夹') !== null).toBe(true);
  });

  it('有记录启动：自动恢复默认序第一名为当前根并进入列表视图（无任何 workspace 动作命令）', async () => {
    await restored();

    expect(screen.getByText(/进行中/) !== null).toBe(true);
    // 恢复为纯查询链：挂载取数 → 以默认序第一名取 change 列表，无动作命令
    expect(commandsExceptEnvironment()).toEqual(['list_workspaces', 'list_changes']);
    expect(countOf('app_environment')).toBe(1);
  });

  it('恢复进入列表后：列表项点击进入详情视图（hash 落 #/changes/<fixture id>），返回列表后「刷新」重发 list_changes', async () => {
    await restored();

    fireEvent.click(screen.getByText('add-feature'));
    await waitFor(() =>
      expect(invokeMock).toHaveBeenCalledWith('get_change_detail', {
        root: FIRST.root,
        id: CHANGE_ID,
      }),
    );
    // 路由段 id 化：URL 段为 change id（非展示名）；详情标题取 detail.name
    expect(window.location.hash).toBe(`#/changes/${CHANGE_ID}`);
    expect(window.location.hash).not.toBe('#/changes/add-feature');
    expect(screen.getByRole('heading', { name: 'add-feature' }) !== null).toBe(true);

    // 刷新按钮随 header 瘦身迁入清单页头部（图标钮 aria-label=刷新）：详情视图内不在场，返回列表后可操作
    expect(screen.queryByRole('button', { name: '刷新' })).toBeNull();
    fireEvent.click(screen.getByRole('button', { name: '← 返回列表' }));
    await waitFor(() => expect(screen.getByRole('button', { name: '刷新' }) !== null).toBe(true));

    const before = invokeMock.mock.calls.filter(([name]) => name === 'list_changes').length;
    fireEvent.click(screen.getByRole('button', { name: '刷新' }));
    await waitFor(() => {
      const after = invokeMock.mock.calls.filter(([name]) => name === 'list_changes').length;
      expect(after).toBe(before + 1);
    });
  });

  it('添加对话框取消（返回 null）：不调用 add_workspace、停留欢迎屏', async () => {
    remaining = [];
    render(<App />);
    await waitFor(() => expect(screen.getByText('添加新文件夹') !== null).toBe(true));

    openMock.mockResolvedValue(null);
    fireEvent.click(screen.getByText('添加新文件夹'));

    await waitFor(() => expect(openMock).toHaveBeenCalled());
    await new Promise((resolve) => setTimeout(resolve, 10));
    expect(commandsExceptEnvironment().every((name) => name === 'list_workspaces')).toBe(true);
    expect(screen.getByText('添加新文件夹') !== null).toBe(true);
  });

  it('添加流以标准参数调用文件夹对话框，并将选中路径入库后打开（欢迎屏「添加新文件夹」入口保留登记）', async () => {
    remaining = [];
    render(<App />);
    await waitFor(() => expect(screen.getByText('添加新文件夹') !== null).toBe(true));

    openMock.mockResolvedValue('C:\\picked');
    fireEvent.click(screen.getByText('添加新文件夹'));

    // 对话框参数契约：目录模式 + 单选
    await waitFor(() =>
      expect(openMock).toHaveBeenCalledWith({ directory: true, multiple: false }),
    );
    await waitFor(() =>
      expect(invokeMock).toHaveBeenCalledWith('add_workspace', { root: 'C:\\picked' }),
    );
    await waitFor(() =>
      expect(invokeMock).toHaveBeenCalledWith('list_changes', { root: 'C:\\picked' }),
    );
    expect(screen.queryByText('添加新文件夹')).toBeNull();
  });
});

