    const expandedShare = Number(panelElement?.style.flexGrow);
    expect(expandedShare, '展开后份额大于窄条份额').toBeGreaterThan(collapsedShare);
  });

  it('页面开关两拍互逆：展开 → 展开体在场；再点 → 回窄条（state 为唯一真源）', async () => {
