/** snake 词 → 活面 camel 词（测试内小表——22 词 round-trip 用）。 */
function normalizeWord(word: RunStepKind): ChangeStepKind {
  const entry = NORMALIZE_EXPECTED.find(([snake]) => snake === word);
  if (!entry) {
    throw new Error(`词汇表缺项: ${word}`);
  }
  return entry[1];
}

